  g_ui.selected_function = UI_DEMO_FUNCTION_WIFI;
  g_ui.has_selection = false;
  g_ui.wifi_view = UI_DEMO_WIFI_VIEW_LIST;
  g_ui.temperature_valid = false;
  g_ui.humidity_valid = false;
  g_ui.brightness_percent =
