int ui_demo_netinfo_refresh(void)
{
  char *task_argv[] =
  {
    "ui_netinfo",
    NULL
  };
  int pid;

  pthread_mutex_lock(&g_netinfo_lock);
  if (!g_netinfo.initialized)
    {
      pthread_mutex_unlock(&g_netinfo_lock);
