  blt.dst_buf.stride[0] = layer->buf.stride[0];
  blt.dst_buf.size.width = layer->buf.size.width;
  blt.dst_buf.size.height = layer->buf.size.height;
  blt.dst_buf.format = layer->buf.format;

  switch (fbi->fb_rotate) {
